input_script='''
let lastInput=null;const inputEvents=[],replacements=[];let priorPage=null,priorSource=null,priorAdvanced=null,priorFooter=null;
function snapshot(event){const page=document.querySelector('.page'),source=document.getElementById('source-host'),advanced=document.querySelector('[data-action=advanced]'),forward=document.querySelector('.footer .primary');if(!page)return null;
const same={page:priorPage===page,source:priorSource===source,advanced:priorAdvanced===advanced,footer:priorFooter===forward};priorPage=page;priorSource=source;priorAdvanced=advanced;priorFooter=forward;
return {event,time:performance.now(),english:lang==='en',dbms:state.dbms,source:{...state.source},target:{...state.target},connected:state.connected,busy:state.busy,advanced:state.advanced,error:state.error,trialReady:state.trial.ready,trialConsent:state.trial.consent,visited:[...state.visited],focus:{id:document.activeElement?.id,action:document.activeElement?.dataset.action,visible:document.activeElement?.matches(':focus-visible')},same,status:[...document.querySelectorAll('.form-head>.pill')].map(x=>x.textContent),success:!!document.querySelector('.notice.ok'),footer:forward?{action:forward.dataset.action,label:forward.textContent.trim(),enabled:!forward.disabled,loading:!!forward.querySelector('.spinner')}:null,opacity:getComputedStyle(page).opacity}}
for(const type of ['input','change','click','keyup'])document.addEventListener(type,e=>{if(e.target.closest('#diagnostics'))return;queueMicrotask(()=>{lastInput=snapshot(type);inputEvents.push(lastInput)});if(type==='click'&&e.target.closest('[data-action=connect]'))setTimeout(()=>{lastInput=snapshot('after550');inputEvents.push(lastInput)},600)});
new MutationObserver(()=>{if(inputEvents.length===0||state.connected!==inputEvents.at(-1)?.connected||state.busy!==inputEvents.at(-1)?.busy){const current=snapshot('render');if(current){lastInput=current;inputEvents.push(current)}}}).observe(document.getElementById('app'),{childList:true,subtree:true});
document.getElementById('connectionpage-reduced').onclick=()=>{window.fixtureReduced=!window.fixtureReduced;document.documentElement.classList.toggle('fixture-reduced',window.fixtureReduced);render();lastInput=snapshot('reduced');inputEvents.push(lastInput)};
let detached=null;document.getElementById('connectionpage-mount').onclick=()=>{const app=document.getElementById('app');if(detached){app.append(...detached);detached=null;lastInput=snapshot('mount');inputEvents.push(lastInput)}else{detached=[...app.childNodes];app.replaceChildren();inputEvents.push({event:'unmount',time:performance.now(),connected:state.connected,advanced:state.advanced})}};
document.getElementById('connectionpage-input-record').onclick=async()=>{const value={dpr:devicePixelRatio,last:lastInput??snapshot('initial'),events:inputEvents};const res=await fetch('/evidence/connection-connectionpage-'+(new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});if(!res.ok)throw Error('Record failed');document.getElementById('connectionpage-input-record').textContent='Input recorded'};
'''
(o/'connectionpage-input.html').write_text('<!doctype html><meta charset="utf-8"><title>ConnectionPage input · original isolation</title><link rel="stylesheet" href="connectionpage-original.css"><a href="#main">Skip to content</a><div id="app"></div><div id="dialog-host"></div><div id="toast-host"></div><div id="announcer" aria-live="polite"></div><input id="file-open" type="file" hidden><div id="diagnostics" style="position:fixed;left:5px;top:5px;z-index:1000"><button id="connectionpage-input-record">Record ConnectionPage input</button><button id="connectionpage-reduced">Reduced</button><button id="connectionpage-mount">Mount</button></div><style>.fixture-reduced *,.fixture-reduced *::before,.fixture-reduced *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}.fixture-reduced .running-dot{opacity:1}.fixture-reduced .spinner{border-color:currentColor;background:currentColor;opacity:.7}</style><script>window.fixtureReduced=false;const nativeMatchMedia=window.matchMedia.bind(window);window.matchMedia=query=>query.includes("prefers-reduced-motion")?{get matches(){return window.fixtureReduced},media:query}:nativeMatchMedia(query);</script><script src="connectionpage-input-original.js"></script><script>'+input_script+'</script>')
